private static void tryToSetStaxProperty(XMLInputFactory factory, String key, boolean value) {
    try {
        factory.setProperty(key, value);
    } catch (IllegalArgumentException e) {
        LOG.warn("StAX Feature unsupported: {}", key, e);
    }
}
